357|export async function cleanSections(
358|  bookTitle: string,
359|  sections: RawSection[],
360|  judge?: Judge,
361|): Promise<{ chapters: CleanChapter[]; report: CleanReport }> {
362|  const removed: RemovedItem[] = [];
363|  const flagged: CleanReport["flagged"] = [];
364|  const merged: CleanReport["merged"] = [];
365|  const pushRemoved = (sec: RawSection, rule: string, kind: string, reason: string): void => {
366|    removed.push(removedFor(sec, rule, kind, reason));
367|  };
368|
369|  let kept = sections.filter((sec) => {
370|    if (!sec.linear) {
371|      pushRemoved(sec, "linear-no", "non_content", 'linear="no" spine item');
372|      return false;
373|    }
374|    return true;
375|  });
376|  kept = kept.filter((sec) => {
377|    const hit = ruleEpubType(sec);
378|    if (hit !== null) {
379|      pushRemoved(sec, "epub-type", hit.kind, hit.reason);
380|      return false;
381|    }
382|    return true;
383|  });
384|  kept = mergeContinuations(kept, merged);
385|  const dropSimple = (rule: (sec: RawSection) => { kind: string; reason: string } | null, name: string): void => {
386|    kept = kept.filter((sec) => {
387|      const hit = rule(sec);
388|      if (hit !== null) {
389|        pushRemoved(sec, name, hit.kind, hit.reason);
390|        return false;
391|      }
392|      return true;
393|    });
394|  };
395|  dropSimple(ruleEmpty, "empty");
396|  dropSimple(rulePgMarkers, "pg-markers");
397|  const confident = new Set(kept.filter(isConfident).map((sec) => sec.id));
398|  const skipConfident = (
399|    rule: (sec: RawSection) => { kind: string; reason: string } | null,
400|    name: string,
401|  ): void => {
402|    kept = kept.filter((sec) => {
403|      if (confident.has(sec.id)) return true;
404|      const hit = rule(sec);
405|      if (hit !== null) {
406|        pushRemoved(sec, name, hit.kind, hit.reason);
407|        return false;
408|      }
409|      return true;
410|    });
411|  };
412|  skipConfident(ruleTitlePolicy(bookTitle), "title-policy");
413|  skipConfident(ruleContentsBody, "contents-body");
414|  skipConfident(ruleAdBody, "ad-body");
415|
416|  let llm: CleanReport["llm"] = null;
417|  const ambiguous = kept.filter((sec) => !confident.has(sec.id));
418|  if (ambiguous.length > 0 && judge !== undefined) {
419|    let result: JudgeResult | null = null;
420|    try {
421|      result = await judge(buildJudgeInput(kept, ambiguous, bookTitle));
422|    } catch {
423|      result = null;
424|    }
425|    if (result === null) {
426|      llm = { model: "unknown", promptTokens: 0, completionTokens: 0, cachedTokens: 0, costUsd: 0, error: "failed" };
427|    } else {
428|      llm = {
429|        model: result.model,
430|        promptTokens: result.promptTokens,
431|        completionTokens: result.completionTokens,
432|        cachedTokens: result.cachedTokens,
433|        costUsd: result.costUsd,
434|      };
435|      const byId = new Map(result.sections.map((v) => [v.id, v]));
436|      const contentIds = new Set(
437|        ambiguous.filter((sec) => byId.get(sec.id)?.verdict === "content" || confident.has(sec.id)).map((sec) => sec.id),
438|      );
439|      for (const c of kept) if (confident.has(c.id)) contentIds.add(c.id);
440|      const after: RawSection[] = [];
441|      ambiguous.forEach((sec) => {
442|        const verdict = byId.get(sec.id);
443|        if (verdict === undefined || verdict.verdict === "content") {
444|          after.push(sec);
445|          return;
446|        }
447|        if (verdict.verdict === "uncertain") {
448|          flagged.push({ sectionId: sec.id, reason: short(verdict.reason, 120) });
449|          after.push(sec);
450|          return;
451|        }
452|        const at = kept.indexOf(sec);
453|        const before = kept.slice(0, at).some((s) => contentIds.has(s.id));
454|        const behind = kept.slice(at + 1).some((s) => contentIds.has(s.id));
455|        if (sectionWords(sec) >= LONG_SECTION_WORDS && before && behind) {
456|          flagged.push({ sectionId: sec.id, reason: short(`long interior section kept despite verdict: ${verdict.reason}`, 120) });
457|          after.push(sec);
458|          return;
459|        }
460|        pushRemoved(sec, "llm", verdict.kind, verdict.reason);
461|      });
462|      const keptIds = new Set(after.map((s) => s.id).concat([...confident]));
463|      kept = kept.filter((sec) => confident.has(sec.id) || keptIds.has(sec.id));
