32|// META-INF/rights.xml means Adobe DRM. An encryption.xml that lists
33|// anything but font obfuscation means the content is encrypted.
34|function assertNoDrm(files: Record<string, Uint8Array>, parse: XmlParser): void {
35|  if ("META-INF/rights.xml" in files) throw new Error("drm");
36|  const enc = files["META-INF/encryption.xml"];
37|  if (enc === undefined) return;
38|  const doc = parse(new TextDecoder().decode(enc), "application/xml");
39|  const algs = byTag(doc, "EncryptionMethod").map((el) => el.getAttribute("Algorithm") ?? "");
40|  if (algs.length > 0 && algs.some((a) => a !== FONT_ALG)) throw new Error("drm");
41|}
42|
43|function opfDir(opfPath: string): string {
44|  const slash = opfPath.lastIndexOf("/");
45|  return slash === -1 ? "" : opfPath.slice(0, slash + 1);
46|}
47|
48|function navLabels(doc: Document, fileOf: (href: string) => string): Map<string, string> {
49|  const labels = new Map<string, string>();
50|  const navs = byTag(doc, "nav");
51|  const toc = navs.find((nav) => (nav.getAttribute("epub:type") ?? "").split(/\s+/).includes("toc")) ?? navs[0] ?? null;
52|  const scope = toc ?? doc.documentElement;
53|  if (scope === null || scope === undefined) return labels;
54|  for (const a of [...scope.getElementsByTagName("a")]) {
55|    const href = a.getAttribute("href");
56|    if (href === null) continue;
57|    labels.set(fileOf(href.split("#")[0] ?? ""), textOf(a));
58|  }
59|  return labels;
60|}
61|
62|function ncxLabels(doc: Document, fileOf: (href: string) => string): Map<string, string> {
63|  const labels = new Map<string, string>();
64|  for (const point of byTag(doc, "navPoint")) {
65|    const label = point.getElementsByTagName("navLabel")[0];
66|    const content = point.getElementsByTagName("content")[0];
67|    const src = content?.getAttribute("src");
68|    if (label !== undefined && src !== undefined && src !== null) {
69|      labels.set(fileOf(src.split("#")[0] ?? ""), textOf(label));
70|    }
71|  }
72|  return labels;
73|}
74|
75|function epubTypes(el: Element): string[] {
76|  const raw = [el.getAttribute("epub:type"), el.getAttributeNS("http://www.idpf.org/2007/ops", "type")];
77|  const out: string[] = [];
78|  for (const value of raw) {
79|    if (value !== null) out.push(...value.split(/\s+/).filter((t) => t.length > 0));
80|  }
81|  return [...new Set(out)];
82|}
83|
84|function spineBlocks(doc: Document): { text: string; heading: boolean }[] {
85|  for (const el of doc.querySelectorAll("script, style")) el.remove();
86|  for (const el of doc.querySelectorAll("[id]")) {
87|    const id = el.getAttribute("id") ?? "";
88|    if (id.startsWith("pg-") || id === "project-gutenberg-license") el.remove();
89|  }
90|  for (const br of doc.getElementsByTagName("br")) br.replaceWith(doc.createTextNode(" "));
91|  const blocks: { text: string; heading: boolean }[] = [];
92|  for (const el of [...doc.querySelectorAll(BLOCK_SELECTOR)]) {
93|    if (el.querySelector(BLOCK_SELECTOR) !== null) continue; // keep leaf blocks only
94|    const text = (el.textContent ?? "").replace(/\s+/g, " ").trim();
95|    if (text.length === 0) continue;
96|    blocks.push({ text, heading: /^h[1-6]$/i.test(el.tagName) });
97|  }
98|  return blocks;
99|}
100|
101|export function readEpubSections(bytes: Uint8Array, parse: XmlParser): EpubBook {
102|  if (bytes.length > MAX_INPUT_BYTES) throw new Error("too_large");
103|  let files: Record<string, Uint8Array>;
104|  try {
105|    files = unzipSync(bytes, { filter: (entry) => entry.originalSize <= MAX_ENTRY_BYTES });
106|  } catch {
107|    throw new Error("not_epub");
108|  }
109|  let total = 0;
110|  for (const data of Object.values(files)) total += data.length;
111|  if (total > MAX_TOTAL_BYTES) throw new Error("too_large");
112|  const decode = (name: string): string => new TextDecoder().decode(files[name]);
113|  assertNoDrm(files, parse);
114|  if (!("META-INF/container.xml" in files)) throw new Error("not_epub");
115|  const rootfile = byTag(parse(decode("META-INF/container.xml"), "application/xml"), "rootfile")[0];
116|  const opfPath = rootfile?.getAttribute("full-path");
117|  if (opfPath === undefined || opfPath === null || !(opfPath in files)) throw new Error("unreadable");
118|  const dir = opfDir(opfPath);
119|  const opf = parse(decode(opfPath), "application/xml");
120|  const title = textOf(byTag(opf, "dc:title")[0] ?? null) || "Untitled";
121|  const authorRaw = textOf(byTag(opf, "dc:creator")[0] ?? null);
122|  const hrefOf = new Map<string, { href: string; media: string; properties: string }>();
123|  const manifest = byTag(opf, "manifest")[0];
124|  if (manifest !== undefined) {
125|    for (const item of [...manifest.getElementsByTagName("item")]) {
126|      const id = item.getAttribute("id");
127|      const href = item.getAttribute("href");
128|      if (id !== null && href !== null) {
129|        hrefOf.set(id, {
130|          href,
131|          media: item.getAttribute("media-type") ?? "",
132|          properties: item.getAttribute("properties") ?? "",
133|        });
134|      }
135|    }
136|  }
137|  const spine = byTag(opf, "spine")[0];
138|  const refs = spine === undefined ? [] : [...spine.getElementsByTagName("itemref")];
139|  if (refs.length === 0) throw new Error("unreadable");
140|  const entryOf = (href: string): string => dir + href;
141|  const fileOf = (href: string): string => href;
142|  let labels = new Map<string, string>();
143|  for (const { href } of hrefOf.values()) {
144|    if (!/\.ncx$/i.test(href)) continue;
145|    const name = entryOf(href);
146|    if (name in files) {
147|      labels = ncxLabels(parse(decode(name), "application/xml"), fileOf);
148|      break;
149|    }
150|  }
151|  for (const { href, media, properties } of hrefOf.values()) {
152|    if (!properties.split(/\s+/).includes("nav")) continue;
153|    if (media !== "" && media !== "application/xhtml+xml" && !/\.x?html?$/i.test(href)) continue;
154|    const name = entryOf(href);
155|    if (!(name in files)) continue;
156|    labels = navLabels(parse(decode(name), "application/xhtml+xml"), fileOf);
157|    break;
158|  }
159|  const sections: RawSection[] = [];
160|  for (const ref of refs) {
161|    const idref = ref.getAttribute("idref");
162|    const manifestItem = idref === null ? undefined : hrefOf.get(idref);
163|    if (manifestItem === undefined) throw new Error("unreadable");
164|    if (manifestItem.media !== "" && manifestItem.media !== "application/xhtml+xml") continue;
165|    const name = entryOf(manifestItem.href);
166|    const data = files[name];
167|    if (data === undefined) throw new Error("unreadable");
168|    const text = new TextDecoder().decode(data);
169|    let doc: Document;
170|    try {
171|      doc = parse(text, "application/xhtml+xml");
172|      if (doc.getElementsByTagName("parsererror").length > 0) doc = parse(text, "text/html");
173|    } catch {
174|      try {
175|        doc = parse(text, "text/html");
176|      } catch {
177|        sections.push({
178|          id: name,
179|          href: manifestItem.href,
180|          linear: true,
181|          types: [],
182|          docTitle: null,
183|          navLabel: labels.get(manifestItem.href) ?? labels.get(manifestItem.href.split("/").pop() ?? "") ?? null,
184|          blocks: [],
185|        });
186|        continue;
187|      }
188|    }
189|    const body = doc.getElementsByTagName("body")[0] ?? doc.documentElement;
190|    const types = body === undefined ? [] : epubTypes(body);
191|    if (body !== undefined) {
192|      for (const child of [...body.children]) {
193|        if (["section", "article", "div"].includes(child.tagName.toLowerCase())) {
194|          types.push(...epubTypes(child));
195|        }
196|      }
197|    }
198|    const titleEl = doc.getElementsByTagName("title")[0];
199|    const docTitle = titleEl === undefined ? null : textOf(titleEl) || null;
200|    const navLabel =
201|      labels.get(manifestItem.href) ?? labels.get(manifestItem.href.split("/").pop() ?? "") ?? null;
202|    sections.push({
203|      id: name,
204|      href: manifestItem.href,
205|      linear: ref.getAttribute("linear") !== "no",
206|      types: [...new Set(types)],
207|      docTitle,
208|      navLabel,
209|      blocks: spineBlocks(doc),
210|    });
211|  }
212|  return { title, author: authorRaw === "" ? null : authorRaw, sections };
213|}

