Read text file `core/clean.ts`.
1|// Cleaning: strip front/back junk before segmentation. Pure: no env reads,
2|// no network. The LLM arrives as an injected judge; tests pass fakes.
3|
4|export interface RawBlock {
5|  text: string;
6|  heading: boolean;
7|}
8|
9|export interface RawSection {
10|  id: string;
11|  href: string;
12|  linear: boolean;
13|  types: string[];
14|  docTitle: string | null;
15|  navLabel: string | null;
16|  blocks: RawBlock[];
17|}
18|
19|export interface JudgeSectionInput {
20|  id: string;
21|  title: string;
22|  words: number;
23|  head: string[];
24|  tail: string[];
25|}
26|
27|export interface JudgeWindowBlock {
28|  index: number;
29|  text: string;
30|}
31|
32|export interface JudgeInput {
33|  sections: JudgeSectionInput[];
34|  headWindow: JudgeWindowBlock[];
35|  tailWindow: JudgeWindowBlock[];
36|}
37|
38|export type JudgeVerdictLabel = "content" | "non_content" | "uncertain";
39|
40|export interface JudgeVerdict {
41|  id: string;
42|  verdict: JudgeVerdictLabel;
43|  kind: string;
44|  reason: string;
45|}
46|
47|export interface JudgeResult {
48|  sections: JudgeVerdict[];
49|  headCut: number;
50|  tailCut: number;
51|  model: string;
52|  promptTokens: number;
53|  completionTokens: number;
54|  cachedTokens: number;
55|  costUsd: number;
56|}
57|
58|export type Judge = (input: JudgeInput) => Promise<JudgeResult | null>;
59|
60|export interface CleanChapter {
61|  title: string;
62|  paragraphs: string[];
63|  sectionIds: string[];
64|}
65|
66|export interface RemovedItem {
67|  sectionId: string;
68|  blockRange: [number, number] | null;
69|  kind: string;
70|  reason: string;
71|  rule: string;
72|  words: number;
73|  preview: string;
74|}
75|
76|export interface CleanReport {
77|  source: "epub" | "gutenberg-txt";
78|  llm: {
79|    model: string;
80|    promptTokens: number;
81|    completionTokens: number;
82|    cachedTokens: number;
83|    costUsd: number;
84|    error?: string;
85|  } | null;
86|  kept: { title: string; paragraphs: number; sectionIds: string[] }[];
87|  removed: RemovedItem[];
88|  flagged: { sectionId: string; reason: string }[];
89|  merged: { from: string; into: string; reason: string }[];
90|}
91|
92|const HEAD_WINDOW = 6;
93|const TAIL_WINDOW = 8;
94|const LONG_SECTION_WORDS = 2000;
95|
96|function countWords(text: string): number {
97|  return text.split(/\s+/).filter((w) => w.length > 0).length;
98|}
99|
100|function sectionWords(sec: Pick<RawSection, "blocks">): number {
101|  return sec.blocks.reduce((n, b) => n + countWords(b.text), 0);
102|}
103|
104|function short(text: string, max: number): string {
105|  return text.length <= max ? text : text.slice(0, max);
106|}
107|
108|function removedFor(
109|  sec: RawSection,
110|  rule: string,
111|  kind: string,
112|  reason: string,
113|  blockRange: [number, number] | null = null,
114|): RemovedItem {
115|  const texts =
116|    blockRange === null ? sec.blocks.map((b) => b.text) : sec.blocks.slice(blockRange[0], blockRange[1] + 1).map((b) => b.text);
117|  return {
118|    sectionId: sec.id,
119|    blockRange,
120|    kind,
121|    reason: short(reason, 120),
122|    rule,
123|    words: texts.reduce((n, t) => n + countWords(t), 0),
124|    preview: short(texts[0] ?? "", 120),
125|  };
126|}
127|
128|// Rule 1: spine items outside the linear reading order are never content.
129|function ruleLinearNo(sec: RawSection): { kind: string; reason: string } | null {
130|  return sec.linear ? null : { kind: "non_content", reason: 'linear="no" spine item' };
131|}
132|
133|// Rule 2: Standard Ebooks types are exact. Keep chapters and bodymatter,
134|// drop front/backmatter. Gutenberg files carry no types and pass through.
135|function ruleEpubType(sec: RawSection): { kind: string; reason: string } | null {
136|  const types = sec.types.map((t) => t.toLowerCase());
137|  if (types.includes("chapter") || types.includes("bodymatter")) return null;
138|  if (types.includes("frontmatter") || types.includes("backmatter")) {
139|    return { kind: "front_matter", reason: `epub:type ${sec.types.join(" ")}` };
140|  }
141|  return null;
142|}
143|
144|// Rule 8 (runs early): a heading-free fragment of at most 30 words whose
145|// docTitle matches the previous kept section continues that section. Runs
146|// before empty/keyword rules so "Holmesly." merges instead of vanishing.
147|function mergeContinuations(
148|  sections: RawSection[],
149|  merged: CleanReport["merged"],
150|): RawSection[] {
151|  const kept: RawSection[] = [];
152|  for (const sec of sections) {
153|    const prev = kept[kept.length - 1];
154|    if (
155|      prev !== undefined &&
156|      sec.docTitle !== null &&
157|      sec.docTitle === prev.docTitle &&
158|      sec.blocks.every((b) => !b.heading) &&
159|      sectionWords(sec) <= 30
160|    ) {
161|      kept[kept.length - 1] = { ...prev, blocks: [...prev.blocks, ...sec.blocks] };
162|      merged.push({ from: sec.id, into: prev.id, reason: `no headings, ${sectionWords(sec)} words, same docTitle` });
163|    } else {
164|      kept.push(sec);
165|    }
166|  }
167|  return kept;
168|}
169|
170|// Rule 3: zero words, or nothing but headings (title pages, license shells).
171|function ruleEmpty(sec: RawSection): { kind: string; reason: string } | null {
172|  if (sectionWords(sec) === 0) return { kind: "empty", reason: "no words" };
173|  if (sec.blocks.length > 0 && sec.blocks.every((b) => b.heading)) {
174|    return { kind: "empty", reason: "heading-only blocks" };
175|  }
176|  return null;
177|}
178|
179|// Rule 4: Gutenberg wrapper sections by docTitle or nav label.
180|function rulePgMarkers(sec: RawSection): { kind: string; reason: string } | null {
181|  const hay = `${sec.docTitle ?? ""} ${sec.navLabel ?? ""}`.toLowerCase();
182|  if (hay.includes("project gutenberg")) return { kind: "boilerplate", reason: "gutenberg wrapper" };
183|  if (/\blicense\b/.test(hay)) return { kind: "license", reason: "license section" };
184|  if (/\bcover\b/.test(hay)) return { kind: "front_matter", reason: "cover section" };
185|  return null;
186|}
187|
188|const TITLE_TERMS: { term: string; kind: string }[] = [
189|  { term: "contents", kind: "contents" },
190|  { term: "transcriber's note", kind: "transcriber_note" },
191|  { term: "transcriber’s note", kind: "transcriber_note" },
192|  { term: "advertisements", kind: "advertisement" },
193|  { term: "advertisement", kind: "advertisement" },
194|  { term: "also by", kind: "advertisement" },
195|  { term: "colophon", kind: "colophon" },
196|  { term: "copyright", kind: "copyright" },
197|  { term: "index", kind: "front_matter" },
198|  { term: "about the author", kind: "about_author" },
199|  { term: "preface", kind: "front_matter" },
200|  { term: "introduction", kind: "front_matter" },
201|  { term: "foreword", kind: "front_matter" },
202|  { term: "prefatory note", kind: "front_matter" },
203|  { term: "title page", kind: "front_matter" },
204|  { term: "titlepage", kind: "front_matter" },
205|  { term: "half-title", kind: "front_matter" },
206|  { term: "halftitle", kind: "front_matter" },
207|  { term: "imprint", kind: "front_matter" },
208|  { term: "dedication", kind: "front_matter" },
209|  { term: "license", kind: "license" },
210|];
211|
212|function matchTitleTerm(guess: string): { kind: string; reason: string } | null {
213|  const g = guess.toLowerCase().trim();
214|  for (const { term, kind } of TITLE_TERMS) {
215|    if (g === term || g.startsWith(term)) return { kind, reason: `title matches "${term}"` };
216|  }
217|  return null;
218|}
219|
220|// First heading that is not the book title. A bare label ("Stave I")
221|// defers to the nav label after the colon; with no headings the docTitle
222|// (then nav label) is the guess.
223|export function deriveTitle(sec: Pick<RawSection, "blocks" | "docTitle" | "navLabel">, bookTitle: string): string {
224|  const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.trim());
225|  const first = heads.find((h) => h.toLowerCase() !== bookTitle.toLowerCase());
226|  if (first === undefined) return sec.docTitle ?? sec.navLabel ?? "Untitled";
227|  const stripped = first
228|    .replace(/^(?:chapter|stave|book|part)\s+[ivxlc0-9]+[.:]?\s*/i, "")
229|    .replace(/^(?:[ivxlc]+|\d+)[.:]?\s+/i, "")
230|    .trim();
231|  if (stripped.length > 0) return stripped;
232|  if (sec.navLabel !== null) {
233|    const colon = sec.navLabel.indexOf(":");
234|    if (colon !== -1 && sec.navLabel.slice(colon + 1).trim().length > 0) {
235|      return sec.navLabel.slice(colon + 1).trim();
236|    }
237|  }
238|  return sec.docTitle ?? sec.navLabel ?? "Untitled";
239|}
240|
241|// Rule 5: front-matter titles. Besides the guess, a bare heading such as
242|// "Contents" on a title page drops the section.
243|function ruleTitlePolicy(bookTitle: string) {
244|  return (sec: RawSection): { kind: string; reason: string } | null => {
245|    const hit = matchTitleTerm(deriveTitle(sec, bookTitle));
246|    if (hit !== null) return hit;
247|    const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.toLowerCase().trim());
248|    for (const { term, kind } of TITLE_TERMS) {
249|      if (heads.includes(term)) return { kind, reason: `heading matches "${term}"` };
250|    }
251|    return null;
252|  };
253|}
254|
255|// Rule 6: contents tables are mostly short entries plus page numbers.
256|function ruleContentsBody(sec: RawSection): { kind: string; reason: string } | null {
257|  const body = sec.blocks.filter((b) => !b.heading);
258|  if (body.length === 0) return null;
259|  const shortCount = body.filter((b) => countWords(b.text) < 6).length;
260|  const numbers = body.filter((b) => /^\d+$/.test(b.text.trim())).length;
261|  if (shortCount / body.length >= 0.6 && numbers >= 3) {
262|    return { kind: "contents", reason: "mostly short entries with page numbers" };
263|  }
264|  return null;
265|}
266|
267|function isAdBlock(text: string): boolean {
268|  const t = text.trim();
269|  if (/\b\d+\s*s\./.test(t)) return true; // 6s., 3s. 6d.
270|  if (/\b\d+\s*s\.(?:\s*\d+\s*d\.)?\s*net\b/i.test(t)) return true; // 6s. net
271|  if (/^\s*net\s*\.?\s*$/i.test(t)) return true; // a whole block reading net
272|  if (/crown\s+8vo/i.test(t)) return true;
273|  if (/in\s+one\s+volume/i.test(t)) return true;
274|  if (/\bprice\b/i.test(t)) return true;
275|  if (/[—–]\s*[“"]/.test(t)) return true; // GLOBE.—"quote"
276|  if (/·|\bmacmillan\b|\blondon\b/i.test(t)) return true; // publisher address
277|  return false;
278|}
279|
280|// Rule 7: publisher ad bodies. `net` counts only price-adjacent or
281|// whole-block, never a bare word in prose.
282|function ruleAdBody(sec: RawSection): { kind: string; reason: string } | null {
283|  if (sec.blocks.length === 0) return null;
284|  const hits = sec.blocks.filter((b) => isAdBlock(b.text)).length;
285|  if (hits / sec.blocks.length >= 0.3) {
286|    return { kind: "advertisement", reason: `${hits} of ${sec.blocks.length} blocks match ad tokens` };
287|  }
288|  return null;
289|}
290|
291|const CHAPTER_LABEL = /^(?:chapter|stave|book|part)\s+[ivxlc0-9]+[.:]?\b/i;
292|const BARE_NUMERAL = /^(?:[ivxlc]+|\d+)[.:]?$/i;
293|
294|// Rule 9: confident content skips keyword rules 5-7 and the LLM.
295|function isConfident(sec: RawSection): boolean {
296|  const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.trim());
297|  if (heads.some((h) => CHAPTER_LABEL.test(h))) return true;
298|  if (sec.navLabel !== null && sec.navLabel.includes(":")) {
299|    if (heads.some((h) => BARE_NUMERAL.test(h))) return true;
300|  }
301|  return false;
302|}
303|
304|const END_MARK = /^(THE END|FINIS)\.?$/i;
305|const PRINTER_PATTERNS = [
306|  /^printed\s+(by|in)\b/i,
307|  /&\s*sons,?\s+limited/i,
308|  /r\.\s*&\s*r\.\s*clark/i,
309|  /limited,?\s+(london|edinburgh)\b/i,
310|];
311|
312|// Rule 10: cut everything after THE END/FINIS in the last kept section,
313|// and drop trailing printer lines only, in every kept section. Printer
314|// lines hide mid-list too (a merged "Sussex." + printer line lands in a
315|// story the ad sections below used to follow). Sign-offs stay.
316|function truncateAfterEnd(sec: RawSection, removed: RemovedItem[]): RawSection {
317|  const endIdx = sec.blocks.map((b) => b.text.trim()).findLastIndex((t) => END_MARK.test(t));
318|  if (endIdx === -1 || endIdx === sec.blocks.length - 1) return sec;
319|  removed.push(removedFor(sec, "tail-cut", "back_matter", "after THE END", [endIdx + 1, sec.blocks.length - 1]));
320|  return { ...sec, blocks: sec.blocks.slice(0, endIdx + 1) };
321|}
322|
323|function stripPrinterLines(sec: RawSection, removed: RemovedItem[]): RawSection {
324|  let end = sec.blocks.length;
325|  while (end > 0 && PRINTER_PATTERNS.some((p) => p.test(sec.blocks[end - 1]?.text.trim() ?? ""))) {
326|    end -= 1;
327|  }
328|  if (end === sec.blocks.length) return sec;
329|  removed.push(removedFor(sec, "tail-cut", "back_matter", "printer line", [end, sec.blocks.length - 1]));
330|  return { ...sec, blocks: sec.blocks.slice(0, end) };
331|}
332|
333|// Rule 11: inside content, drop headings, illustration placeholders,
334|// and Gutenberg page anchors.
335|function toParagraphs(sec: RawSection): string[] {
336|  return sec.blocks
337|    .filter((b) => !b.heading && !/^\[illustration/i.test(b.text.trim()) && !/^\[pg\s*\d+\]$/i.test(b.text.trim()))
338|    .map((b) => b.text);
