115|  const rootfile = byTag(parse(decode("META-INF/container.xml"), "application/xml"), "rootfile")[0];
116|  const opfPath = rootfile?.getAttribute("full-path");
117|  if (opfPath === undefined || opfPath === null || !(opfPath in files)) throw new Error("unreadable");
118|  const dir = opfDir(opfPath);
