+const END_MARK = /^(THE END|FINIS)\.?$/i;
+const PRINTER_PATTERNS = [
+  /^printed\s+(by|in)\b/i,
+  /&\s*sons,?\s+limited/i,
+  /r\.\s*&\s*r\.\s*clark/i,
